  ('SV_AREA_A5', 'SD_AREA', 'A5', '5㎡', 5, '㎡', '["5㎡内", "5平米"]', 'PLATFORM', 5, 'ACTIVE', 'MAIN', NOW(), 'SYSTEM', NOW(), 'SYSTEM'),
